#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <mma.h>
using namespace nvcuda;
#define BM 128
#define BN 128
#define BK 16
#define BKA (BK + 8)  // A smem row stride: 24 floats (96B), 32B-aligned rows for WMMA
#define BNP (BN + 8)  // B smem row stride: 136 floats (544B), padded + 32B-aligned for WMMA
#define WM 32         // warp tile M
#define WN 64         // warp tile N
#define STAGES 3      // cp.async pipeline depth (number of shared-memory tile buffers)
// ---- cp.async helpers (sm_80+) ----
// Copies 16 bytes global->shared; src_bytes < 16 zero-fills the remainder.
__device__ __forceinline__ void cp_async16(void* smem_dst, const void* gmem_src, int src_bytes) {
    unsigned dst = (unsigned)__cvta_generic_to_shared(smem_dst);
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16, %2;\n"
                 :: "r"(dst), "l"(gmem_src), "r"(src_bytes));
}
__device__ __forceinline__ void cp_async_commit() {
    asm volatile("cp.async.commit_group;\n" ::);
}
__device__ __forceinline__ void cp_async_wait1() {
    asm volatile("cp.async.wait_group 1;\n" ::);
}
__device__ __forceinline__ void cp_async_wait0() {
    asm volatile("cp.async.wait_group 0;\n" ::);
}
// Round a float to tf32 precision (kept in an f32 container).
__device__ __forceinline__ float to_tf32(float x) {
    unsigned u;
    asm volatile("cvt.rna.tf32.f32 %0, %1;\n" : "=r"(u) : "f"(x));
    return __uint_as_float(u);
}
// Tiled shared-memory SGEMM: C(MxN) = A(MxK) * B(KxN)
// Each block computes a 128x128 tile of C; each of the 8 warps computes a 32x64 sub-tile.
// Optimization: TF32 tensor-core WMMA with error-compensated 3xTF32 splitting
// (hi = tf32(x), lo = x - hi; A*B ~= hi*hi + hi*lo + lo*hi). This runs the MMAs on
// the tensor cores while preserving ~fp32 accuracy (the dropped lo*lo term is O(2^-22)).
// Operands are staged in shared memory through the same cp.async double-buffered
// pipeline as before, using padded 32B-aligned rows that match the WMMA load layout.
__global__ void __launch_bounds__(256) matmul_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int M, int N, int K,
                              bool vec_ok) {
