    float (*As)[BKA] = reinterpret_cast<float(*)[BKA]>(smem);                      // stage-major: [STAGES*BM][BKA]
    float (*Bs)[BNP] = reinterpret_cast<float(*)[BNP]>(smem + STAGES * BM * BKA);  // stage-major: [STAGES*BK][BNP]
