    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int bm = blockIdx.y * BM;
    const int bn = blockIdx.x * BN;
    // warp sub-tile origin: 4x2 warp grid -> 32x64 warp tiles
    const int warpRow = (warp >> 1) * WM;  // 0, 32, 64, 96
    const int warpCol = (warp & 1) * WN;   // 0, 64
    // loader indices for the A tile (BM x BK), 16B copies: 4 threads/row, 64 rows/pass
    const int aRow = tid / (BK / 4);
    const int aCol = (tid % (BK / 4)) * 4;
    // loader indices for the B tile (BK x BN), 16B copies: 32 threads/row, 8 rows/pass
    const int bRow = tid / (BN / 4);
    const int bCol = (tid % (BN / 4)) * 4;
    wmma::fragment<wmma::accumulator, 16, 16, 8, float> acc[WM / 16][WN / 16];
    #pragma unroll
    for (int i = 0; i < WM / 16; ++i)
        #pragma unroll
        for (int j = 0; j < WN / 16; ++j)
            wmma::fill_fragment(acc[i][j], 0.0f);
    // ---- Compute on the resident tile in buffer `buf` with tensor-core MMA ----
    auto computeTile = [&](int buf) {
        wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::row_major> aHi[WM / 16], aLo[WM / 16];
        wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::row_major> bHi[WN / 16], bLo[WN / 16];
        #pragma unroll
        for (int ks = 0; ks < BK; ks += 8) {
            #pragma unroll
            for (int i = 0; i < WM / 16; ++i) {
                wmma::load_matrix_sync(aHi[i], &As[buf * BM + warpRow + i * 16][ks], BKA);
                #pragma unroll
                for (int e = 0; e < (int)aHi[i].num_elements; ++e) {
                    float h = to_tf32(aHi[i].x[e]);
                    aLo[i].x[e] = aHi[i].x[e] - h;
                    aHi[i].x[e] = h;
                }
            }
            #pragma unroll
            for (int j = 0; j < WN / 16; ++j) {
                wmma::load_matrix_sync(bHi[j], &Bs[buf * BK + ks][warpCol + j * 16], BNP);
                #pragma unroll
                for (int e = 0; e < (int)bHi[j].num_elements; ++e) {
                    float h = to_tf32(bHi[j].x[e]);
                    bLo[j].x[e] = bHi[j].x[e] - h;
                    bHi[j].x[e] = h;
                }
            }
