        // vec_ok guarantees K%4==0 and N%4==0, so every in-bounds 16B copy is aligned
        // and fully inside the matrix row (gCol%4==0 && gCol<K => gCol+3<K).
        auto loadTileAsync = [&](int k0, int buf) {
            #pragma unroll
            for (int r = 0; r < BM; r += 64) {
                int gRow = bm + aRow + r;
                int gCol = k0 + aCol;
                const float* src = A;
                int bytes = 0;
                if (gRow < M && gCol < K) {
                    src = A + (long)gRow * K + gCol;
                    bytes = 16;
                }
                cp_async16(&As[buf * BM + aRow + r][aCol], src, bytes);
            }
            #pragma unroll
            for (int r = 0; r < BK; r += 8) {
                int gRow = k0 + bRow + r;
                int gCol = bn + bCol;
                const float* src = B;
                int bytes = 0;
                if (gRow < K && gCol < N) {
                    src = B + (long)gRow * N + gCol;
                    bytes = 16;
                }
                cp_async16(&Bs[buf * BK + bRow + r][bCol], src, bytes);
            }
            cp_async_commit();
        };
        // ---- Prologue: fill the first STAGES-1 pipeline stages ----
        #pragma unroll
        for (int s = 0; s < STAGES - 1; ++s) loadTileAsync(s * BK, s);
        int cur = 0;
        for (int k0 = 0; k0 < K; k0 += BK) {
            const int kfetch = k0 + (STAGES - 1) * BK;
            // Wait until the current tile's copy group has landed; up to
            // STAGES-2 prefetch groups may still be in flight.
            cp_async_wait1();
            __syncthreads();
            computeTile(cur);
            // Buffer (cur + STAGES - 1) % STAGES held the tile computed in the
            // previous iteration; the __syncthreads() above guarantees every warp
            // is done reading it, so it can be refilled immediately and the copy
            // overlaps the following iterations' MMA work (deeper pipeline).
            if (kfetch < K) loadTileAsync(kfetch, (cur + STAGES - 1) % STAGES);
            cur = (cur + 1) % STAGES;
        }
    } else {
        // ---- Generic fallback (unaligned K/N): scalar loads, same double buffering ----
        auto loadTile = [&](int k0, int buf) {
            #pragma unroll
            for (int r = 0; r < BM; r += 64) {
                int gRow = bm + aRow + r;
                #pragma unroll
                for (int c = 0; c < 4; ++c) {
                    int gCol = k0 + aCol + c;
                    As[buf * BM + aRow + r][aCol + c] =
                        (gRow < M && gCol < K) ? A[(long)gRow * K + gCol] : 0.f;
                }
            }
            #pragma unroll
            for (int r = 0; r < BK; r += 8) {
                int gRow = k0 + bRow + r;
                #pragma unroll
                for (int c = 0; c < 4; ++c) {
                    int gCol = bn + bCol + c;
                    Bs[buf * BK + bRow + r][bCol + c] =
                        (gRow < K && gCol < N) ? B[(long)gRow * N + gCol] : 0.f;
                }
            }
        };
        loadTile(0, 0);
        __syncthreads();
        int cur = 0;
        for (int k0 = 0; k0 < K; k0 += BK) {
            const int knext = k0 + BK;
            if (knext < K) loadTile(knext, cur ^ 1);
            computeTile(cur);
            if (knext < K) {
                __syncthreads();
                cur ^= 1;
            }
        }
    }
    // ---- Write results (As is dead now; reuse it as per-warp 16x16 staging) ----
    __syncthreads();
    float* stage = smem;  // As/Bs are dead now; reuse dynamic smem as per-warp 16x16 staging
    #pragma unroll
    for (int i = 0; i < WM / 16; ++i) {
        #pragma unroll
        for (int j = 0; j < WN / 16; ++j) {
            const int gRow = bm + warpRow + i * 16;
            const int gCol = bn + warpCol + j * 16;
            if (gRow >= M || gCol >= N) continue;
            if (vec_ok && gRow + 16 <= M && gCol + 16 <= N) {
                wmma::store_matrix_sync(C + (long)gRow * N + gCol, acc[i][j], N,
                                        wmma::mem_row_major);
            } else {
                float* st = stage + warp * 256;
                wmma::store_matrix_sync(st, acc[i][j], 16, wmma::mem_row_major);
                __syncwarp();
                #pragma unroll
                for (int t = 0; t < 8; ++t) {
                    const int idx = lane + t * 32;
                    const int rr = gRow + (idx >> 4);
                    const int cc = gCol + (idx & 15);
                    if (rr < M && cc < N) C[(long)rr * N + cc] = st[idx];
                }
                __syncwarp();
            }
        }
    }
}
